<?php
session_start(); require_once __DIR__.'/config/database.php'; $error=''; $success='';
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL);$pass=$_POST['password']??'';
