?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Create account | NovaCart</title><link rel="stylesheet" href="css/style.css"></head><body><header class="site-header"><a class="logo" href="index.php">Nova<span>Cart</span></a><nav class="nav"><a href="index.php">Home</a><a href="products.php">Shop</a><a href="login.php">Login</a></nav></header><main class="auth-wrap"><form class="auth-card" method="post"><p class="eyebrow">JOIN NOVACART</p><h1>Create account</h1><p class="muted">Save your details and make shopping easier.</p><?php if($error): ?><div class="alert error"><?= htmlspecialchars($error) ?></div><?php endif; ?><?php if($success): ?><div class="alert success"><?= htmlspecialchars($success) ?></div><?php endif; ?><label>Full name<input name="name" required maxlength="100" autocomplete="name" value="<?= htmlspecialchars($_POST['name']??'') ?>"></label><label>Email address<input type="email" name="email" required autocomplete="email" value="<?= htmlspecialchars($_POST['email']??'') ?>"></label><label>Password<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><button class="btn full-btn" type="submit">Create account</button><p class="auth-switch">Already have an account? <a href="login.php">Log in</a></p></form></main><script src="js/script.js"></script></body></html>